/// <summary>
/// Makes Credit limit read-only on the Customers form, except for an existing customer
/// and a user with the Edit customer credit limit privilege.
/// </summary>
[ExtensionOf(formDataSourceStr(CustTable, CustTable))]
final class DYLO_CustTableFormCustTableDS_Extension
{
}

Method.Source:
public int active()
{
    int ret = next active();

    CustTable custTableRecord = this.cursor();
    this.object(fieldNum(CustTable, CreditMax)).allowEdit(
        custTableRecord.RecId != 0 && DYLO_CustCreditLimitRequestWFProcessor::canEditCreditLimit());

    return ret;
}
